import { defineConfig } from "@kubb/core";
import { pluginClient } from "@kubb/plugin-client";
import { type Exclude, pluginOas } from "@kubb/plugin-oas";
import { type PluginReactQuery, pluginReactQuery } from "@kubb/plugin-react-query";
import { pluginTs } from "@kubb/plugin-ts";

import type { QueryKeyOptions } from "@/types/query-key";

const ignoreBanner = `
// biome-ignore-all lint: auto-generated by Kubb
// @ts-nocheck
// This file is auto-generated by Kubb, do not modify it manually.
`;

// ? Operations/tags the generator ignores: `{ pattern: "Webhook", type: "tag" }`, `{ pattern: "oldOp", type: "operationId" }`.
const exclude: Exclude[] = [];

interface QueryKeyGeneratorProps {
	additionalProps?: QueryKeyOptions;
}

function queryKeyGenerator({ additionalProps = {} }: QueryKeyGeneratorProps = {}): PluginReactQuery["options"]["queryKey"] {
	return ({ operation, schemas }) => {
		const keys: string[] = [];

		const pathParams = schemas.pathParams?.keys ?? [];
		const queryParams = schemas.queryParams?.keys ?? [];
		const operationId = operation.getOperationId();

		const props: string[] = [];

		if (operationId) {
			props.push(`operationId: "${operationId}"`);
		}

		if ("x-cache-entity" in operation.schema) {
			keys.push(operation.schema["x-cache-entity"] as string);
		}

		if ("x-pagination-type" in operation.schema) {
			props.push(`paginationType: "${operation.schema["x-pagination-type"]}"`);
		}

		if ("x-data-shape" in operation.schema) {
			props.push(`dataShape: "${operation.schema["x-data-shape"]}"`);
		}

		Object.entries(additionalProps).forEach(([key, value]) => {
			props.push(`${key}: ${JSON.stringify(value)}`);
		});

		if (pathParams.length > 0 && queryParams.length > 0) {
			props.push(`...{ ${pathParams.join(", ")} }`, "...(params || {})");
		} else if (pathParams.length > 0) {
			props.push(`${pathParams.join(", ")}`, `operationId: "${operationId}"`);
		} else if (queryParams.length > 0) {
			props.push("...(params || {})", `operationId: "${operationId}"`);
		}

		return [...keys.map((k) => `"${k}"`), `{ ${props.join(", ")} }`].filter(Boolean);
	};
}

export default defineConfig({
	root: ".",
	input: {
		path: "./openapi.json",
	},
	output: {
		path: "./src/gen/api",
		clean: true,
		format: undefined,
		lint: undefined,
		extension: undefined,
		barrelType: false,
	},
	plugins: [
		pluginOas(),
		pluginTs({
			output: {
				path: "models",
				banner: ignoreBanner,
			},
		}),
		pluginClient({
			paramsType: "object",
			importPath: "@/lib/axios",
			urlType: "export", // export url functions, ex: getSseUrl()
			exclude,
			output: {
				path: "clients",
				barrelType: false,
				banner: ignoreBanner,
			},
		}),
		pluginReactQuery({
			paramsType: "object",
			exclude,
			output: {
				path: "hooks",
				barrelType: false,
				banner: ignoreBanner,
			},
			client: {
				importPath: "@/lib/axios",
			},
			customOptions: {
				importPath: "@/hooks/use-custom-hook-options",
				name: "useCustomHookOptions",
			},
			queryKey: queryKeyGenerator(),
			mutationKey: ({ operation }) => {
				const keys: string[] = [];

				if ("x-cache-entity" in operation.schema) {
					keys.push(operation.schema["x-cache-entity"] as string);
				}

				return [...keys.map((k) => `"${k}"`), `{ operationId: "${operation.getOperationId()}" }`];
			},
			infinite: {
				queryParam: "cursor",
				initialPageParam: undefined,
				nextParam: "meta.nextCursor",
			},
		}),
	],
});
